pub fn perform_operations(a: u32, b: u32) -> u32 {
    let safe_b = if b == 0 { 1 } else { b };
    let shift = b % 32;

    let add = a.wrapping_add(b);
    let sub = a.wrapping_sub(b);
    let mul = a.wrapping_mul(b);
    let div = a / safe_b;
    let shl = a.wrapping_shl(shift);
    let shr = a >> shift;
    let xor = a ^ b;
    let and = a & b;
    let or = a | b;
    let not_a = !a;

    add ^ sub ^ mul ^ div ^ shl ^ shr ^ xor ^ and ^ or ^ not_a
}
